-- Environment context schema. Generated by go run ./cmd/environment-schema.
CREATE TABLE IF NOT EXISTS `environment_object` (`id` integer PRIMARY KEY AUTOINCREMENT,`group_id` integer,`name` text,`kind` text,`description` text,`revision` integer,`deleted` numeric,`updated_at` integer);
CREATE INDEX IF NOT EXISTS `idx_environment_object_deleted` ON `environment_object`(`deleted`);
CREATE INDEX IF NOT EXISTS `idx_environment_object_group_id` ON `environment_object`(`group_id`);
CREATE TABLE IF NOT EXISTS `environment_relation` (`id` integer PRIMARY KEY AUTOINCREMENT,`identity` text,`from_ref` text,`to_ref` text,`kind` text,`status` text,`from_version` text,`to_version` text,`source` text,`note` text,`valid_until` integer,`created_by` integer,`updated_by` integer,`updated_at` integer,`revision` integer,CONSTRAINT `uni_environment_relation_identity` UNIQUE (`identity`));
CREATE INDEX IF NOT EXISTS `idx_environment_relation_status` ON `environment_relation`(`status`);
CREATE INDEX IF NOT EXISTS `idx_environment_relation_to_ref` ON `environment_relation`(`to_ref`);
CREATE INDEX IF NOT EXISTS `idx_environment_relation_from_ref` ON `environment_relation`(`from_ref`);
CREATE TABLE IF NOT EXISTS `environment_change` (`id` integer PRIMARY KEY AUTOINCREMENT,`relation_id` integer,`object_ref` text,`actor_id` integer,`action` text,`detail` text,`created_at` integer);
CREATE INDEX IF NOT EXISTS `idx_environment_change_created_at` ON `environment_change`(`created_at`);
CREATE INDEX IF NOT EXISTS `idx_environment_change_object_ref` ON `environment_change`(`object_ref`);
CREATE INDEX IF NOT EXISTS `idx_environment_change_relation_id` ON `environment_change`(`relation_id`);
CREATE TABLE IF NOT EXISTS `environment_discovery` (`version_id` integer,`actor_id` integer,`state` text,`note` text,`next_run` integer,`lease_until` integer,`updated_at` integer,PRIMARY KEY (`version_id`));
CREATE INDEX IF NOT EXISTS `idx_environment_discovery_next_run` ON `environment_discovery`(`next_run`);
